?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Evidence Refresh Review | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}.wrap{max-width:1180px;margin:32px auto;padding:0 20px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.top a{color:#123b67}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.filters button,.action{padding:9px 12px;border-radius:9px;border:1px solid #cbd5e1;background:#fff;cursor:pointer}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin:14px 0}.meta{color:#64748b;font-size:13px}.url{word-break:break-all}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.actions button{padding:9px 12px;border:0;border-radius:9px;background:#123b67;color:#fff;cursor:pointer}.actions button.secondary{background:#475569}.actions button.reject{background:#991b1b}textarea{width:100%;box-sizing:border-box;min-height:70px;margin-top:10px;padding:10px;border:1px solid #cbd5e1;border-radius:9px}.empty{padding:30px;text-align:center;color:#64748b}</style></head><body><main class="wrap"><div class="top"><div><h1>Evidence Refresh Review</h1><p>Review detected source changes before any structured fact extraction or canonical-data update.</p></div><a href="/admin">Back to Admin</a></div><div class="filters"><button data-status="pending_review">Pending</button><button data-status="needs_fact_extraction">Needs fact extraction</button><button data-status="no_material_change">No material change</button><button data-status="rejected">Rejected</button><button data-status="all">All</button></div><div id="msg"></div><section id="list"><div class="empty">Loading…</div></section></main><script>
let csrf='',current='pending_review';const list=document.getElementById('list'),msg=document.getElementById('msg');const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function load(status=current){current=status;msg.textContent='';const r=await fetch('/api/evidence-refresh/candidates?status='+encodeURIComponent(status));const d=await r.json();if(!r.ok){list.innerHTML='<div class="empty">Unable to load candidates.</div>';return}csrf=d.csrf_token||'';if(!(d.candidates||[]).length){list.innerHTML='<div class="empty">No candidates in this view.</div>';return}list.innerHTML=d.candidates.map(c=>`<article class="card" data-id="${c.id}"><h3>${esc(c.product_name)} · ${esc(c.source_title)}</h3><p class="meta">Vendor: ${esc(c.vendor_name||'Unknown')} · Status: ${esc(c.status)} · Detected: ${esc(c.detected_at)} · Source checked: ${esc(c.checked_at||'—')}</p><p class="url"><a href="${esc(c.source_url)}" target="_blank" rel="noreferrer">${esc(c.source_url)}</a></p><p class="meta">Latest refresh: ${esc(c.latest_refresh_state||'—')}<br>Previous fingerprint: ${esc(c.previous_fingerprint||'initial')}<br>Current fingerprint: ${esc(c.current_fingerprint)}</p><textarea maxlength="4000" placeholder="Reviewer notes">${esc(c.review_notes||'')}</textarea>${c.status==='pending_review'?`<div class="actions"><button data-act="needs_fact_extraction">Escalate for fact extraction</button><button class="secondary" data-act="no_material_change">No material fact change</button><button class="reject" data-act="rejected">Reject candidate</button></div>`:''}</article>`).join('');}
async function disposition(card,status){const notes=card.querySelector('textarea').value;const r=await fetch('/api/evidence-refresh/candidates/'+card.dataset.id+'/disposition',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({status,review_notes:notes})});const d=await r.json();if(!r.ok){msg.textContent=d.error||'Unable to update candidate';return}msg.textContent='Candidate updated.';load();}
document.querySelector('.filters').onclick=e=>{const b=e.target.closest('[data-status]');if(b)load(b.dataset.status)};list.onclick=e=>{const b=e.target.closest('[data-act]');if(b)disposition(b.closest('[data-id]'),b.dataset.act)};load();
</script></body></html>